static bool CopyTree(const wstring& from,const wstring& to){if(!CreateDirectoryW(to.c_str(),NULL))return false;WIN32_FIND_DATAW data;HANDLE f=FindFirstFileW((from+L"\\*").c_str(),&data);if(f==INVALID_HANDLE_VALUE)return false;bool ok=true;do{if(!wcscmp(data.cFileName,L".")||!wcscmp(data.cFileName,L".."))continue;if(data.dwFileAttributes&FILE_ATTRIBUTE_REPARSE_POINT){ok=false;break;}wstring source=from+L"\\"+data.cFileName,target=to+L"\\"+data.cFileName;if(data.dwFileAttributes&FILE_ATTRIBUTE_DIRECTORY){if(!CopyTree(source,target)){ok=false;break;}}else if(!CopyFileW(source.c_str(),target.c_str(),TRUE)){ok=false;break;}}while(FindNextFileW(f,&data));if(ok&&GetLastError()!=ERROR_NO_MORE_FILES)ok=false;FindClose(f);return ok;}
static bool Shortcut(const wstring& directory){IShellLinkW* link=NULL;if(FAILED(CoCreateInstance(CLSID_ShellLink,NULL,CLSCTX_INPROC_SERVER,IID_IShellLinkW,(void**)&link)))return false;link->SetPath((directory+L"\\RRFF.exe").c_str());link->SetWorkingDirectory(directory.c_str());link->SetDescription(TITLE);link->SetIconLocation((directory+L"\\RRFF.exe").c_str(),0);IPersistFile* file=NULL;HRESULT hr=link->QueryInterface(IID_IPersistFile,(void**)&file);if(SUCCEEDED(hr)){wstring dest=KnownFolder(CSIDL_DESKTOPDIRECTORY)+L"\\RRFF FATX Formatter.lnk";if(GetFileAttributesW(dest.c_str())!=INVALID_FILE_ATTRIBUTES)hr=HRESULT_FROM_WIN32(ERROR_FILE_EXISTS);else hr=file->Save(dest.c_str(),TRUE);file->Release();}link->Release();return SUCCEEDED(hr);}
